import * as React from "react";
import { Box, Grid, Card, CardContent, Typography } from "@mui/material";

export default function HomePage({ onSelect }: { onSelect: (page: string) => void }) {
  // Handle card click to change content
  const handleCardClick = (page: string) => {
    onSelect(page); // Update active page based on card clicked
  };

  // Cards for each section
  const cardItems = [
    { label: "Venues", value: "venues" },
    { label: "Hair", value: "hair" },
    { label: "Makeup", value: "makeup" },
    { label: "Photographers", value: "photographers" },
    { label: "Music", value: "music" },
    { label: "Florist", value: "florist" },
    { label: "Dresser", value: "dresser" },
    { label: "Planner", value: "planner" },
  ];

  return (
    <Box sx={{ paddingTop: "80px", padding: 4 }}>
      {/* Home page content, restored layout */}
      <Typography variant="h4" sx={{ textAlign: "center", marginBottom: 4, fontWeight: "bold" }}>
        Welcome to Our Wedding Planner
      </Typography>

      <Typography variant="h6" sx={{ textAlign: "center", marginBottom: 4 }}>
        Choose a category to explore the services we offer.
      </Typography>

      {/* Display Cards for Different Sections */}
      <Grid container spacing={3} justifyContent="center">
        {cardItems.map((item) => (
          <Grid item xs={12} sm={6} md={4} key={item.value}>
            <Card
              sx={{
                cursor: "pointer",
                boxShadow: "0px 4px 8px rgba(0,0,0,0.1)",
                "&:hover": { boxShadow: "0px 6px 12px rgba(0,0,0,0.2)" },
              }}
              onClick={() => handleCardClick(item.value)} // Card click handler
            >
              <CardContent>
                <Typography variant="h6" sx={{ textAlign: "center", fontWeight: "bold" }}>
                  {item.label}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>
    </Box>
  );
}


